package com.novacommerce.order.api.error; import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class OrderExceptionHandler{@ExceptionHandler(OrderException.class)ResponseEntity<ApiError>known(OrderException e,HttpServletRequest r){return ResponseEntity.status(e.status()).body(new ApiError(Instant.now(),e.status().value(),e.code(),e.getMessage(),r.getRequestURI()));}@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class})ResponseEntity<ApiError>bad(Exception e,HttpServletRequest r){return ResponseEntity.badRequest().body(new ApiError(Instant.now(),400,"VALIDATION_FAILED","Request validation failed",r.getRequestURI()));}public record ApiError(Instant timestamp,int status,String code,String message,String path){}}
